from pathlib import Path
import json,sys
P=Path(__file__).resolve().parent
B=P.parents[4]
sys.path.insert(0,str(B))
import substantive_impact as impact
base=P.parent/'edition001'
(P/'source.json').write_bytes((base/'source.json').read_bytes())
rows=json.loads((base/'answer.json').read_text())
sources=json.loads((P/'source.json').read_text());by={x['number']:x for x in sources}

def effect(kind,measure,description,before,after,source_quote,proposed_quote,population,transition,replacement,unit='legal_duty'):
    return dict(kind=kind,measure_id=measure,description=description,before=before,after=after,unit=unit,source_quote=source_quote,proposed_quote=proposed_quote,affected_population=population,conditions_and_transition=transition,replacement_or_new_burdens=replacement)

for row in rows:
    n=row['number'];effects=[];category='material_reduction'
    limits='Aucune économie budgétaire ni réduction du délai total d’instruction n’est chiffrée. Les autres fondements de consultation, de sécurité, de participation et de recours conservent leur champ.'
    new='Aucune attestation, déclaration, autorisation ni condition de remplacement n’est créée. Les garanties existantes expressément conservées ne constituent pas des obligations nouvelles.'
    if n in ['L121-32','L121-34']:
        sq="après avis de la ou des communes intéressées et au vu du résultat d'une enquête publique"
        pq="La ou les communes intéressées peuvent présenter leurs observations dans le cadre de cette enquête ; aucun avis ni délibération distincts ne sont requis sur le seul fondement du présent article"
        effects=[effect('obligation_merged','servitude-participation-communale','Participation communale dans l’enquête existante, sans avis séparé. Une seule mesure partagée par les deux articles législatifs et leur règlement.','Enquête publique puis avis communal séparé.','Participation communale possible dans la même enquête ; aucun avis séparé.',sq,pq,'État et communes concernés par les servitudes de passage littoral.','Décisions à compter de la réforme, procédures en cours comprises ; enquête, propriétaires, conditions de fond et recours conservés.','Aucune consultation de remplacement ; les observations utilisent l’enquête déjà requise.')]
        assessment='La charge réellement retirée est le circuit communal distinct de l’enquête, pas la servitude ni les conditions qui protègent les propriétaires. Les deux articles et R121-23 forment une seule mesure, à dédupliquer.'
    elif n=='R121-23':
        effects=[effect('coordination','servitude-participation-communale','Retrait de la délibération et du délai de deux mois qui rétabliraient l’avis supprimé aux articles législatifs.','Délibération des conseils municipaux, avec silence favorable après deux mois.','Aucun avis distinct ; les observations sont recueillies dans l’enquête.',"le préfet soumet à la délibération des conseils municipaux des communes intéressées le tracé et les caractéristiques du projet de servitude.","Aucune délibération ni consultation communale distincte n'est requise après celle-ci sur le seul fondement du présent article ; le délai de deux mois attaché à cette délibération ne s'applique plus.",'État, communes et porteurs de projets de servitude.','Décisions nouvelles et procédures en cours ; aucun recommencement d’enquête.','Le délai légal d’attente disparaît ; aucune économie automatique de deux mois sur le calendrier total n’est promise.'),effect('regime_merged','servitude-approbation-prefectorale','Unifier les deux voies d’approbation préfet/Conseil d’État en une décision préfectorale.','Opposition d’une commune : décret en Conseil d’État ; sinon arrêté du préfet.','Le préfet approuve par arrêté même en cas d’opposition, sous conditions légales et contrôle du juge.',"2° D'un décret en Conseil d'Etat, en cas d'opposition d'une ou plusieurs communes.","1° D'un arrêté du préfet, y compris lorsqu'une ou plusieurs communes ont exprimé leur opposition au projet ;",'État et communes dans les procédures avec opposition communale.','Décisions à compter de la réforme ; actes déjà pris et recours préservés.','L’approbation motivée du préfet et l’enquête restent requises : il ne s’agit pas d’une suppression de toute autorisation.')]
        assessment='Deux éléments sont distingués : coordination de la même participation communale et suppression spécifique de l’escalade Conseil d’État. La première ne constitue pas une troisième consultation supprimée.'
    elif n=='R121-24':
        effects=[effect('obligation_removed','servitude-publicite-sans-presse','Retrait de la publication de la mention dans deux journaux.','Deux insertions dans des journaux régionaux ou locaux, en plus des publicités officielle, communale et foncière.','Les deux insertions de presse ne sont plus requises ; les autres publicités demeurent.',"Mention de cet acte est insérée en caractères apparents dans deux journaux régionaux ou locaux diffusés dans le ou les départements concernés.","Aucune insertion dans des journaux régionaux ou locaux n'est exigée sur le seul fondement du présent article.",'État et collectivités assurant la publicité des actes de servitude.','Formalités restant à accomplir après réforme, actes antérieurs compris ; validité et recours déjà ouverts préservés.','Pas de nouvelle publication ou attestation en remplacement ; les publicités de l’enquête sur d’autres fondements restent applicables.')]
        assessment='Une obligation de publicité dans deux journaux est retirée dans ce dispositif. Les deux annonces ne sont pas comptées comme deux dispositifs ni comme une baisse nationale de coûts démontrée.'
    elif n=='R121-29':
        category='mixed'
        effects=[effect('relief_extended','servitude-indemnisation-delai','Retrait de la forclusion spéciale de six mois, sans nouveau délai uniforme inventé.','Le propriétaire doit demander l’indemnité dans les six mois du dommage sous peine de forclusion.','Pour les dommages futurs, aucune forclusion spéciale de six mois ; les prescriptions autonomes restent applicables.',"La demande d'indemnité doit, à peine de forclusion, parvenir au préfet dans le délai de six mois à compter de la date où le dommage a été causé.","Pour les dommages causés à compter de l'entrée en vigueur de la réforme des articles L. 121-32 et L. 121-34, la demande n'est plus soumise à la forclusion spéciale de six mois prévue par la rédaction antérieure du présent article.",'Propriétaires indemnisables pour les dommages causés par les servitudes littorales.','Dommages futurs seulement ; dommages anciens, forclusions acquises et décisions définitives non rouverts.','Les prescriptions de droit commun ne sont pas abrogées. L’exposition éventuelle de l’État à des demandes plus tardives n’est pas chiffrée.',unit='other'),effect('obligation_removed','servitude-indemnisation-envoi','Fin de l’exclusivité du recommandé postal ou du déplacement au guichet.','Transmission limitée au recommandé postal ou au dépôt contre décharge en préfecture.','Tout moyen établissant la réception est possible ; les deux voies antérieures restent ouvertes.',"Elle doit être adressée au préfet par lettre recommandée avec demande d'avis de réception postal ou être déposée contre décharge à la préfecture.","La demande d'indemnité est adressée au préfet par tout moyen permettant d'établir la date de sa réception, y compris par lettre recommandée avec demande d'avis de réception ou par dépôt contre décharge à la préfecture.",'Demandeurs d’indemnité de servitude littorale.','Demandes adressées après réforme, y compris pour dommages anciens dans leurs délais ; pas de nouveau dépôt des dossiers reçus.','La preuve de réception demeure ; aucune plateforme ou formulaire nouveau n’est imposé.'),effect('obligation_removed','servitude-indemnisation-pieces','Fin de la production répétée des preuves déjà légalement disponibles.','La demande doit comprendre les documents de propriété et justification du préjudice.','Le demandeur ne reproduit pas les pièces exactes et à jour déjà détenues légalement par le service.',"1° Tout document attestant que le demandeur est propriétaire du terrain grevé par la servitude ;",'Les documents exacts et à jour déjà légalement détenus par le service compétent sont réutilisés sans nouvelle production par le demandeur.','Demandeurs d’indemnité et service instructeur.','Demandes adressées après réforme ; preuves nécessaires manquantes ou modifiées encore requises.','Le service réutilise ses pièces disponibles ; pas de nouvelle collecte générale.'),effect('obligation_added','servitude-indemnisation-pieces','Instruction expresse de réemploi imposée au service au lieu de demander à nouveau les pièces.','Le texte spécial énumère les pièces à joindre sans instruction expresse de réemploi par le service.','Le service doit réutiliser les pièces exactes et à jour légalement disponibles.',"La demande doit comprendre :",'Les documents exacts et à jour déjà légalement détenus par le service compétent sont réutilisés sans nouvelle production par le demandeur.','Service compétent chargé des demandes d’indemnisation.','Même champ et même date que la dispense de nouvelle production.','Instruction au service signalée explicitement ; aucun registre ni nouvelle catégorie de donnée. Les obligations générales de réemploi peuvent déjà exister sur d’autres fondements.')]
        assessment='Le texte allège l’envoi et les pièces et supprime une forclusion spéciale pour les dommages futurs. La prolongation de l’exposition de l’État aux demandes et l’instruction de réemploi justifient la classe mixed, sans bénéfice budgétaire net présumé.'
        new='Une instruction explicite de réemploi est adressée au service et la disparition du délai spécial peut exposer l’État à des demandes plus tardives. Aucun registre, formulaire ni contrôle nouveau n’est imposé au demandeur ; le solde net de gestion n’est pas mesuré.'
        limits='Les autres prescriptions et conditions de réparation demeurent. La disparition de la forclusion n’est pas une économie automatique de délai ni de budget : les demandes plus tardives et leur gestion peuvent avoir un coût, non chiffré ici.'
    else:
        category='coordination_only'
        effects=[effect('coordination','hlm-interets-moratoires-plafond','Mettre le règlement en cohérence avec le plafond déjà posé au L431-2.','Le ministre fixe un taux impératif d’intérêts moratoires.','Le ministre fixe le plafond ; le taux contractuel plus favorable et le taux légal subsidiaire suivent L431-2.',"Un arrêté du ministre chargé de la construction et de l'habitation et du ministre chargé des finances fixe le taux des intérêts moratoires en cas de retard dans le cas prévu par l'article L. 431-2.","Un arrêté du ministre chargé de la construction et de l'habitation et du ministre chargé des finances fixe le taux plafond des intérêts moratoires applicable en cas de retard dans le remboursement des prêts mentionnés à l'article L. 431-2.",'Emprunteurs des prêts de L431-2 et bénéficiaires des renvois favorables à ce plafond.','Intérêts futurs sur contrats nouveaux ou en cours ; intérêts déjà courus et délai de recouvrement de trois mois conservés.','Aucun nouvel intérêt ni taux ; le gain du plafond est celui du dispositif L431-2, sans second allègement compté.')]
        assessment='Coordination réglementaire du dispositif de plafond moratoire déjà proposé au L431-2. Le même measure_id est utilisé ; le présent article ne revendique aucune baisse distincte de prélèvement ou de taux.'
    row['substantive_impact']=dict(version=1,classification=category,assessment=assessment,scope_limitations=limits,new_burdens_review=new,effects=effects)
    impact.validate(row,by[n],required=True)

(P/'answer.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
assert all(a['proposed_xml']==b['proposed_xml']for a,b in zip(rows,json.loads((base/'answer.json').read_text())))
print('Six impacts validés, corps des articles strictement identiques à édition001.')
